 + human visual title/author review, sheet5"}]}},{"relation":"catalog_work_descriptions","ref":"description:59","key":{"work_id":59,"language":"nl"},"before":null,"after":{"work_id":59,"language":"nl","bound_author_id":49,"text":"Schrijver Paul Sheldon wordt op een afgelegen boerderij vastgehouden door Annie Wilkes, een bewonderaarster van zijn werk. Zij accepteert niet dat hij haar favoriete personage Misery heeft laten sterven. Terwijl Paul lichamelijk van haar afhankelijk is, dwingt Annie hem een ander vervolg te schrijven. Zijn beroep, dat eerst de reden voor zijn gevangenschap is, wordt ook een mogelijk middel om zich tegen haar controle te verzetten.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1571189/misery.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-06-20261101","evidence":[{"url":"https://metadata.isbn.nl/1571189/misery.html","sha256":"c9a977820c8ee4a654fc7c30c17a223cc3d5b1a970848934c513df118a084050","checkedAt":"2026-11-01T14:06:29.637Z","fact":"Paperback ISBN 9789021035475 verschijningsdatum 21/09/2022 NUR 332 Thriller imprint Luitingh Sijthoff uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sourceAuthors":"Stephen King","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"editions","ref":"edition:9789029090483","key":{"isbn_13":"9789029090483"},"before":null,"after":{"work_id":68,"title":"Liefde in tijden van cholera","language":"nld","isbn_13":"9789029090483","isbn_10":null,"open_library_edition_id":null,"publisher":"Meulenhoff Boekerij B.V."}},{"relation":"catalog_edition_metadata","ref":"metadata:9789029090483","key":{"edition_id":"@edition:9789029090483"},"before":null,"after":{"edition_id":"@edition:9789029090483","work_id":68,"bound_author_id":35,"bound_title"