denissen samen. Het boek onderzoekt hoe wetenschappelijke vooruitgang, commerciële belangen en vragen over zeggenschap met elkaar botsen wanneer menselijk lichaamsmateriaal een zelfstandig bestaan in laboratoria krijgt.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/994300/het-onsterfelijke-leven-van-henrietta-lacks.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-06-20261101","evidence":[{"url":"https://metadata.isbn.nl/994300/het-onsterfelijke-leven-van-henrietta-lacks.html","sha256":"ead2a43099f0f92141203eec4b21420ad40df7859dc5fa53d2d21d94ae64ee1f","checkedAt":"2026-11-01T14:02:48.479Z","fact":"Paperback ISBN 9789046822982 verschijningsdatum 23/10/2017 NUR 686 Moderne geschiedenis (1870-heden) imprint Nieuw Amsterdam uitgever Park Uitgevers taal Nederlands","sourceAuthors":"Rebecca Skloot","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"editions","ref":"edition:9789047009009","key":{"isbn_13":"9789047009009"},"before":null,"after":{"work_id":81,"title":"Ons feilbare denken","language":"nld","isbn_13":"9789047009009","isbn_10":null,"open_library_edition_id":null,"publisher":"Atlas Contact, Uitgeverij"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789047009009","key":{"edition_id":"@edition:9789047009009"},"before":null,"after":{"edition_id":"@edition:9789047009009","work_id":81,"bound_author_id":68,"bound_title":"Ons feilbare denken","bound_language":"nld","bound_isbn13":"9789047009009","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000478356_Ons_feilbare_denken_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/128673/ons-feilbare-denken.html","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed